def has_path(collection, path):
    if not isinstance(collection, dict):
        return False
    path = path.split('\')
    current = collection
    for part in path:
        if part in current:
            current = current[part]
        else:
            return False
    return True

def get_in(collection, path):
    if not isinstance(collection, dict):
        return None
    path = path.split('\')
    current = collection
    for part in path:
        if part in current:
            current = current[part]
        else:
            return None
    return current

def update_in(collection, path, value):
    if not isinstance(collection, dict):
        return collection
    if path == '':
        return value
    path = path.split('\')[:-1]
    current = collection
    for part in path:
        if part not in current:
            current[part] = {}
        current = current[part]
    current[path[-1]] = value
    return collection

def zip_dicts(dict1, dict2):
    result = {}
    for key in set(dict1) | set(dict2):
        if key in dict1 and key in dict2:
            result[key] = dict1[key], dict2[key]
    return result

